let data=Store.load(),lang=Store.pref('lang','ru'),theme=Store.pref('theme','dark'),view='home',filter='all',query='',slide=0,worldData=null,mapBox={x:0,y:0,w:1000,h:500},mapDrag=null,detailId=null,detailTab='route',deferredInstall=null;
if(!copy[lang])lang='ru';if(!['dark','light'].includes(theme))theme='dark';
const $=s=>document.querySelector(s),t=k=>copy[lang][k]||k,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),local=v=>typeof v==='object'&&v!==null?v[lang]||v.ru||v.en||'':v||'',cn=(id,fallback)=>countries[id]?.[lang==='ru'?0:1]||fallback||id,uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2),date=d=>new Date(d+'T12:00:00').toLocaleDateString(lang==='ru'?'ru-RU':'en-GB',{day:'numeric',month:'short',year:'numeric'}),range=tr=>`${date(tr.start)} — ${date(tr.end)}`,duration=tr=>Math.round((new Date(tr.end)-new Date(tr.start))/864e5)+1;
function persist(){if(!Store.save(data))toast(t('storageError'))}
let toastTimer;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function footer(){return `<footer><span>travelsplit ✳ &nbsp; ${t('footer')}</span><span>${t('local')}</span></footer>`}
function setTheme(){document.documentElement.dataset.theme=theme;$('meta[name="theme-color"]').content=theme==='dark'?'#28211c':'#f1eae0';$('#theme').setAttribute('aria-label',lang==='ru'?'Сменить светлую / тёмную тему':'Switch light / dark theme');$('#theme').setAttribute('aria-pressed',String(theme==='light'))}
function nav(){const items=[['home','home'],['trips','trip'],['bookings','booking'],['atlas','map'],['photos','photo']];$('#desktop-nav').innerHTML=items.map(([v])=>`<button data-view="${v}" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''}>${t(v)}</button>`).join('');$('#mobile-nav').innerHTML=items.map(([v,i])=>`<button data-view="${v}" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''}>${icon(i)}${t(v)}</button>`).join('');$('#language').innerHTML=lang==='ru'?'RU <span>/ EN</span>':'EN <span>/ RU</span>';$('#profile').textContent=currentMember().displayName?.[0]?.toUpperCase()||'А';$('#profile').classList.toggle('has-invitations',data.invitations.some(i=>i.inviteeUserId===currentMember().id&&i.status==='PENDING'));$('#profile').setAttribute('aria-label',t('profile'));$('#close-modal').setAttribute('aria-label',t('close'));document.documentElement.lang=lang;document.title=lang==='ru'?'travelsplit — ваш личный атлас':'travelsplit — your personal atlas';document.querySelectorAll('nav').forEach(n=>n.setAttribute('aria-label',lang==='ru'?'Навигация':'Navigation'));setTheme()}
function navigate(v){if(!['home','trips','bookings','atlas','photos'].includes(v))v='home';view=v;filter='all';query='';history.replaceState(null,'','#'+v);render();window.scrollTo({top:0,behavior:'instant'})}
function tripCard(tr){return `<button class="trip-card" data-trip="${esc(tr.id)}"><div class="trip-photo"><img src="assets/${esc(tr.image||'mountains')}.jpg" alt="${esc(local(tr.name))}" loading="lazy"><span class="pill">${icon(tr.status==='completed'?'check':'calendar')}${t(tr.status)}</span></div><div class="trip-content"><span class="eyebrow">${esc(local(tr.country))}</span><h3>${esc(local(tr.name))}</h3><div class="trip-bottom"><span>${icon('calendar')}${range(tr)}</span>${icon('chevron')}</div></div></button>`}
function stats(){const count=new Set(data.places.map(p=>p.country)).size,days=visibleTrips().filter(tr=>tr.status==='completed').reduce((s,tr)=>s+duration(tr),0);return `<div class="stats-strip">${[[count,'countries'],[data.places.length,'cities'],[visibleTrips().length,'journeys'],[days,'days']].map(([n,k])=>`<div class="stat"><strong>${String(n).padStart(2,'0')}</strong><span>${t(k)}</span></div>`).join('')}</div>`}
function heroTrip(){const options=visibleTrips().filter(tr=>tr.status==='planned');return (options.length?options:visibleTrips())[slide%Math.max(1,options.length||visibleTrips().length)]}
function home(){const tr=heroTrip();return `<div class="page"><section class="hero"><svg class="contours" viewBox="0 0 1400 650" preserveAspectRatio="none" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="1.5"><path d="M-60 510C160 680 390 250 530 530s310 190 410-20 350 30 500-60"/><path d="M910-40c-60 210 300 130 215 340s210 260 330 170"/><path d="M925-40c-60 210 300 130 215 340s210 260 330 170"/><path d="M940-40c-60 210 300 130 215 340s210 260 330 170"/><circle cx="582" cy="405" r="18"/></g></svg><div class="hero-copy"><span class="eyebrow">${t('personal')}</span><h1>${t('hero')}</h1><p class="welcome">${t('welcome')} ${esc(currentMember().displayName)}.</p><p class="description">${t('intro')}</p><button class="primary" ${tr?`data-trip="${esc(tr.id)}"`:'data-action="create-trip"'}>${tr?t('open'):t('create')}${icon('trip')}</button><div class="hero-foot"><span class="asterisk">✳</span><p>${t('moments')}</p><button class="text-button" data-view="trips">${t('allTrips')}${icon('trip')}</button></div></div><div class="hero-visual"><div class="hero-back"></div><img class="photo-back" src="assets/forest.jpg" alt="" fetchpriority="high"><img class="photo-front" src="assets/${esc(tr?.image||'mountains')}.jpg" alt="${esc(tr?local(tr.name):t('mountains'))}" fetchpriority="high"><button class="hero-label" ${tr?`data-trip="${esc(tr.id)}"`:'data-action="create-trip"'}><span class="eyebrow">${t('next')}</span><div class="serif">${esc(tr?local(tr.name):t('newChapter'))}</div><small>${tr?range(tr):t('newChapterSub')}</small><span class="label-icon">${icon('trip')}</span></button><div class="carousel"><span class="carousel-count">${tr?slide%Math.max(1,visibleTrips().filter(tr=>tr.status==='planned').length||visibleTrips().length)+1:0} / ${visibleTrips().filter(tr=>tr.status==='planned').length||visibleTrips().length}</span><div class="carousel-controls"><button class="icon-button" data-action="prev" aria-label="${lang==='ru'?'Предыдущая поездка':'Previous trip'}">${icon('left')}</button><button class="icon-button" data-action="next" aria-label="${lang==='ru'?'Следующая поездка':'Next trip'}">${icon('chevron')}</button></div></div></div></section>${stats()}<section><div class="section-head"><div><span class="eyebrow">${t('yourSpace')}</span><h2>${t('everything')}</h2></div></div><div class="section-shortcuts">${[['trips','trip','tripSub'],['bookings','booking','bookingSub'],['atlas','map','atlasSub'],['photos','photo','photoSub']].map(([v,i,s])=>`<button class="shortcut" data-view="${v}"><span class="shortcut-icon">${icon(i)}</span><span><strong>${t(v)}</strong><small>${t(s)}</small></span></button>`).join('')}</div></section><section><div class="section-head"><div><span class="eyebrow">${t('upcoming')}</span><h2>${t('upcomingTitle')}</h2></div><button class="text-button" data-view="trips">${t('allTrips')}</button></div><div class="trip-grid">${visibleTrips().filter(tr=>tr.status==='planned').slice(0,2).map(tripCard).join('')}<button class="trip-card create-card" data-action="create-trip"><span class="icon-button">${icon('plus')}</span><h3 class="serif" style="font-size:31px">${t('newChapter')}</h3><p>${t('newChapterSub')}</p></button></div></section><section class="journal-banner"><div><h2>${t('banner')}</h2><p>${t('bannerSub')}</p></div><button class="primary" data-view="atlas">${t('explore')}${icon('map')}</button></section>${footer()}</div>`}
function trips(){return `<div class="page"><div class="section-head"><div><span class="eyebrow">${t('trips')}</span><h1 style="font-size:clamp(46px,5vw,74px);margin:20px 0">${t('tripsTitle')}</h1><p>${t('tripsIntro')}</p></div><button class="primary" data-action="create-trip">${icon('plus')}${t('create')}</button></div><div class="filters"><div class="segmented" role="group" aria-label="${t('status')}">${['all','planned','completed'].map(k=>`<button data-filter="${k}" class="${filter===k?'active':''}" aria-pressed="${filter===k}">${t(k)}</button>`).join('')}</div><div class="search">${icon('search')}<input id="trip-search" aria-label="${t('search')}" placeholder="${t('search')}" value="${esc(query)}" type="search"></div></div><div class="trip-grid" id="trip-results">${tripResults()}</div>${footer()}</div>`}
function tripResults(){const list=visibleTrips().filter(tr=>(filter==='all'||tr.status===filter)&&`${local(tr.name)} ${local(tr.country)}`.toLowerCase().includes(query.toLowerCase()));return list.length?list.map(tripCard).join(''):`<div class="empty">${t(query?'noResults':'noTrips')}${!query?`<br><button class="primary" data-action="create-trip">${icon('plus')}${t('create')}</button>`:''}</div>`}
function bookingName(b){return lang==='en'&&b.titleEn?b.titleEn:b.title}
function money(b){return b.amount?new Intl.NumberFormat(lang==='ru'?'ru-RU':'en-GB',{style:'currency',currency:b.currency||'RUB',maximumFractionDigits:0}).format(Number(b.amount)):'—'}
function bookingRow(b){const tr=data.trips.find(tr=>tr.id===b.tripId);return `<article class="booking"><div class="booking-icon">${icon(b.type)}</div><div><span class="eyebrow">${esc(tr?local(tr.name):t('trip'))} · ${t(b.type)}</span><h3>${esc(bookingName(b))}</h3><small>${esc(b.code||'—')}</small></div><div class="booking-date"><small>${t('date')}</small><p style="margin-top:7px">${date(b.date)}</p></div><div class="booking-price"><small>${t('cost')}</small><p style="margin-top:7px">${money(b)}</p></div><div class="booking-actions"><span class="pill">${t('saved')}</span><button class="ghost" data-booking="${esc(b.id)}">${t('details')}</button></div></article>`}
function bookings(){return `<div class="page"><div class="section-head"><div><span class="eyebrow">${t('bookingEyebrow')}</span><h1 style="font-size:clamp(45px,5vw,74px);margin:20px 0">${t('bookingTitle')}</h1><p>${t('bookingIntro')}</p></div><button class="primary" data-action="create-booking">${icon('plus')}${t('addBooking')}</button></div><div class="filters"><div class="segmented" role="group" aria-label="${t('type')}">${['all','flight','stay','other'].map(k=>`<button data-booking-filter="${k}" class="${filter===k?'active':''}" aria-pressed="${filter===k}">${t(k)}</button>`).join('')}</div></div><div class="booking-list">${visibleBookings().filter(b=>filter==='all'||(filter==='other'?!['flight','stay'].includes(b.type):b.type===filter)).map(bookingRow).join('')||`<div class="empty">${t('emptyBookings')}</div>`}</div><p class="inline-note">${t('demo')}</p>${footer()}</div>`}
function atlasWorld(){const grouped={};for(const p of data.places)(grouped[p.country]??=[]).push(p);return `<div class="page"><div class="section-head"><div><span class="eyebrow">${t('atlasEyebrow')}</span><h1 style="font-size:clamp(48px,5vw,74px);margin:20px 0">${t('atlasTitle')}</h1><p>${t('atlasIntro')}</p></div><button class="primary" data-action="create-place">${icon('plus')}${t('addPlace')}</button></div>${stats()}<div class="atlas-layout"><div class="map-panel"><div class="map-top"><span class="eyebrow">${t('atlas')}</span></div><div class="map-tip" id="map-tip" role="status"></div><div id="world-map"><div class="map-loading">${lang==='ru'?'Разворачиваем карту…':'Unfolding the map…'}</div></div><div class="map-legend"><i></i>${t('visited')}</div><div class="map-controls"><button data-zoom="in" aria-label="${lang==='ru'?'Приблизить':'Zoom in'}">+</button><button data-zoom="out" aria-label="${lang==='ru'?'Отдалить':'Zoom out'}">−</button><button data-zoom="reset">${t('reset')}</button></div></div><aside class="atlas-sidebar"><span class="eyebrow">${t('myPlaces')}</span><h3 class="serif">${data.places.length} ${lang==='ru'?'точек на карте':'places on the map'}</h3>${Object.entries(grouped).map(([id,places])=>`<div class="country-row"><div class="country-title"><span>${esc(cn(id))}</span><span style="color:var(--muted)">${places.length}</span></div><div class="city-chips">${places.map(p=>`<button class="city-chip" data-place="${esc(p.id)}">${esc(lang==='en'?p.cityEn||p.city:p.city)}</button>`).join('')}</div></div>`).join('')||`<p class="description">${t('atlasIntro')}</p>`}<button class="primary" data-action="create-place">${icon('plus')}${t('addPlace')}</button><p class="atlas-note">${t('mapHint')}</p></aside></div>${footer()}</div>`}
function render(){ensureCollaboration();disposeAtlasMap();nav();$('#main').innerHTML=({home,trips,bookings,atlas,photos:photoAlbums}[view])();if(view==='atlas')mountAtlas();hydratePhotos()}
function openModal(label,html){$('#modal').classList.remove('photo-lightbox');$('#modal-label').textContent=label;$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function closeModal(){$('#modal').classList.remove('photo-lightbox');$('#modal').close();detailId=null}
function field(label,name,opts={}){return `<label class="field ${opts.full?'full':''}">${label}<input name="${name}" ${opts.type?`type="${opts.type}"`:'type="text"'} ${opts.required?'required':''} ${opts.min!==undefined?`min="${opts.min}"`:''} ${opts.max!==undefined?`max="${opts.max}"`:''} ${opts.step?`step="${opts.step}"`:''} maxlength="${opts.maxlength||200}" placeholder="${esc(opts.placeholder||'')}" value="${esc(opts.value||'')}"></label>`}
function selectField(label,name,options,value,full=false){return `<label class="field ${full?'full':''}">${label}<select name="${name}">${options.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`}
function formActions(text=t('save')){return `<p class="error" id="form-error" role="alert"></p><div class="form-actions"><button type="button" class="ghost" data-action="cancel">${t('cancel')}</button><button class="primary" type="submit">${text}</button></div>`}
function createTrip(){openModal(t('newChapter'),`<h2>${t('create')}</h2><form id="trip-form"><div class="form-grid">${field(t('title'),'name',{required:true,full:true,placeholder:t('tripName')})}${field(t('country'),'country',{required:true,full:true,placeholder:t('countryPlaceholder')})}${field(t('start'),'start',{type:'date',required:true})}${field(t('end'),'end',{type:'date',required:true})}${selectField(t('status'),'status',[['planned',t('planned')],['completed',t('completed')]],'planned')}${selectField(t('cover'),'image',['mountains','forest','italy','japan'].map(k=>[k,t(k)]),'mountains')}<label class="field full">${t('notes')}<textarea name="notes" maxlength="10000" placeholder="${t('notesPlaceholder')}"></textarea></label></div>${formActions(t('create'))}</form>`)}
function createBooking(tripId){if(!visibleTrips().length){toast(t('emptyTripBooking'));createTrip();return}openModal(t('bookings'),`<h2>${t('addBooking')}</h2><form id="booking-form"><div class="form-grid">${selectField(t('trip'),'tripId',visibleTrips().map(tr=>[tr.id,local(tr.name)]),tripId||visibleTrips()[0].id,true)}${selectField(t('type'),'type',['flight','stay','train','car','other'].map(k=>[k,t(k)]),'flight')}${field(t('date'),'date',{type:'date',required:true})}${field(t('bookingName'),'title',{required:true,full:true,placeholder:t('bookingPlaceholder')})}${field(t('bookingCode'),'code',{placeholder:t('optional'),full:true})}${field(t('cost'),'amount',{type:'number',min:0,step:'.01',placeholder:t('optional')})}${selectField(t('currency'),'currency',[['RUB','₽ · RUB'],['EUR','€ · EUR'],['USD','$ · USD'],['KZT','₸ · KZT'],['GBP','£ · GBP']],'RUB')}</div>${formActions()}</form>`)}
function bookingDetail(id){const b=data.bookings.find(b=>b.id===id);if(!b)return;const tr=data.trips.find(tr=>tr.id===b.tripId);openModal(t(b.type),`<h2>${esc(bookingName(b))}</h2><div class="detail-meta"><span class="pill">${icon('calendar')}${date(b.date)}</span><span class="pill">${money(b)}</span></div><div class="itinerary-item"><span>${t('trip')}</span><strong>${esc(tr?local(tr.name):'—')}</strong></div><div class="itinerary-item"><span>${t('bookingCode')}</span><strong>${esc(b.code||'—')}</strong></div><p class="form-note">${t('demo')}</p><div class="form-actions"><button class="ghost danger" data-delete-booking="${esc(id)}">${t('delete')}</button>${tr?`<button class="primary" data-trip="${esc(tr.id)}">${t('viewTrip')}</button>`:''}</div>`)}
function tripDetail(id,tab='route'){if(!canViewTrip(id)){toast(ct('noAccess'));return}const tr=data.trips.find(tr=>tr.id===id);if(!tr)return;detailId=id;detailTab=tab;const days=duration(tr);let content='';if(tab==='route')content=`<div class="itinerary-item"><span class="day">01</span><span>${t('arrival')}</span></div>${days>2?`<div class="itinerary-item"><span class="day">02${days>3?'–'+String(days-1).padStart(2,'0'):''}</span><span>${t('exploration')}</span></div>`:''}${days>1?`<div class="itinerary-item"><span class="day">${String(days).padStart(2,'0')}</span><span>${t('returnHome')}</span></div>`:''}<p class="form-note">${t('planHint')}</p>`;if(tab==='bookings'){const list=visibleBookings().filter(b=>b.tripId===id);content=list.map(b=>`<div class="itinerary-item">${icon(b.type)}<div style="flex:1"><strong style="font-size:13px">${esc(bookingName(b))}</strong><p style="font-size:12px;color:var(--muted);margin-top:6px">${date(b.date)}</p></div><button class="ghost" data-booking="${esc(b.id)}">${t('details')}</button></div>`).join('')||`<p class="detail-text">${t('noBookingTrip')}</p>`;content+=`<div class="form-actions"><button class="primary" data-add-trip-booking="${esc(id)}">${icon('plus')}${t('addBooking')}</button></div>`}if(tab==='notes')content=`<form id="notes-form" data-id="${esc(id)}"><label class="field">${t('notes')}<textarea name="notes" style="min-height:150px" maxlength="10000" placeholder="${t('notesPlaceholder')}">${esc(local(tr.notes))}</textarea></label><div class="form-actions"><button type="submit" class="primary">${t('saveNotes')}</button></div></form>`;if(tab==='members')content=membersPanel(id);if(tab==='photos')content=tripAlbums(id);openModal(local(tr.country),`<img class="detail-cover" src="assets/${esc(tr.image||'mountains')}.jpg" alt="${esc(local(tr.name))}"><h2 style="margin-bottom:15px">${esc(local(tr.name))}</h2><div class="detail-meta"><span class="pill">${icon('calendar')}${range(tr)}</span><button class="pill" data-toggle-status="${esc(id)}">${icon(tr.status==='completed'?'check':'calendar')}${t(tr.status)}</button></div><p class="detail-text">${esc(local(tr.notes))}</p>${memberSummary(id)}<div class="segmented detail-tabs">${[['route','route'],['members','members'],['photos','photos'],['bookings','tripBookings'],['notes','tripNotes']].map(([v,k])=>`<button data-detail-tab="${v}" class="${tab===v?'active':''}" aria-pressed="${tab===v}">${t(k)}</button>`).join('')}</div>${content}${canManageTrip(id)?`<div class="form-actions" style="justify-content:flex-start"><button class="text-button danger" data-delete-trip="${esc(id)}">${icon('trash')}${t('delete')}</button></div>`:''}`)}
function createPlace(){openModal(t('atlas'),`<h2>${t('addPlace')}</h2><form id="place-form"><div class="form-grid">${selectField(t('quickCity'),'preset',[['',t('customCity')],...cityPresets.map((c,i)=>[String(i),c[lang==='ru'?0:1]])],'',true)}${field(t('city'),'city',{required:true})}${field(t('cityEn'),'cityEn',{placeholder:t('optional')})}${selectField(t('country'),'country',Object.entries(countries).sort((a,b)=>cn(a[0]).localeCompare(cn(b[0]),lang)).map(([id])=>[id,cn(id)]),'RUS',true)}${field(t('latitude'),'lat',{type:'number',required:true,min:-90,max:90,step:'any'})}${field(t('longitude'),'lon',{type:'number',required:true,min:-180,max:180,step:'any'})}</div><p class="form-note">${t('coordinatesHint')}</p>${formActions()}</form>`)}
function placeDetail(id){const p=data.places.find(p=>p.id===id);if(!p)return;openModal(cn(p.country),`<h2>${esc(lang==='en'?p.cityEn||p.city:p.city)}</h2><p class="detail-text">${icon('pin')} ${Number(p.lat).toFixed(3)}, ${Number(p.lon).toFixed(3)}</p><div class="form-actions"><button class="ghost danger" data-delete-place="${esc(id)}">${t('removePlace')}</button><button class="primary" data-focus-place="${esc(id)}">${t('atlas')}</button></div>`)}
function profileLegacy(){openModal('travelsplit ✳',`<h2>${t('profile')}</h2><div class="profile-info"><span class="avatar">${esc(data.profile?.[0]||'А')}</span><div><strong>${esc(data.profile)}</strong><p>${t('appReady')}</p></div></div><form id="profile-form">${field(t('profileName'),'profile',{required:true,value:data.profile,maxlength:40})}<div class="form-actions"><button class="primary" type="submit">${t('save')}</button></div></form><p class="form-note">${t('deviceData')}</p><div class="form-actions" style="justify-content:flex-start;flex-wrap:wrap"><button class="ghost" data-action="export">${t('export')}</button><label class="ghost" style="cursor:pointer">${t('import')}<input type="file" id="import-data" accept="application/json,.json" hidden></label></div><div class="itinerary-item"><button class="text-button" data-action="install">${t('install')}</button></div>`)}
function geoPath(geometry){const poly=geometry.type==='Polygon'?[geometry.coordinates]:geometry.coordinates;return poly.map(p=>p.map(r=>r.map(([lon,lat],i)=>`${i?'L':'M'}${((lon+180)/360*1000).toFixed(2)},${((90-lat)/180*500).toFixed(2)}`).join('')+'Z').join('')).join('')}
async function drawMap(){if(!worldData){try{const res=await fetch('world.geojson');if(!res.ok)throw Error();worldData=await res.json()}catch(e){if($('#world-map'))$('#world-map').innerHTML=`<div class="map-loading">${t('mapError')}</div>`;return}}if(view!=='atlas'||!$('#world-map'))return;const visited=new Set(data.places.map(p=>p.country));$('#world-map').innerHTML=`<svg class="world" viewBox="${mapBox.x} ${mapBox.y} ${mapBox.w} ${mapBox.h}" role="group" aria-label="${t('mapLabel')}"><g>${worldData.features.filter(f=>f.id!=='ATA').map(f=>`<path class="map-country ${visited.has(f.id)?'visited':''}" d="${geoPath(f.geometry)}" data-country="${esc(f.id)}" data-country-name="${esc(f.properties.name)}" fill-rule="evenodd" tabindex="0" role="button" aria-label="${esc(cn(f.id,f.properties.name))}"><title>${esc(cn(f.id,f.properties.name))}</title></path>`).join('')}</g><g id="map-pins">${data.places.map(p=>{const x=(p.lon+180)/360*1000,y=(90-p.lat)/180*500;return `<g class="map-marker" data-place="${esc(p.id)}" role="button" tabindex="0" aria-label="${esc(lang==='en'?p.cityEn||p.city:p.city)}" transform="translate(${x} ${y})"><circle r="4.5"/><text x="8" y="-7">${esc(lang==='en'?p.cityEn||p.city:p.city)}</text></g>`}).join('')}</g></svg>`;applyMapBox()}
function applyMapBox(){const svg=$('svg.world');if(!svg)return;svg.setAttribute('viewBox',`${mapBox.x} ${mapBox.y} ${mapBox.w} ${mapBox.h}`);const scale=mapBox.w/Math.max(280,svg.clientWidth||1000);document.querySelectorAll('.map-marker').forEach(el=>{const p=data.places.find(p=>p.id===el.dataset.place);if(p)el.setAttribute('transform',`translate(${(p.lon+180)/360*1000} ${(90-p.lat)/180*500}) scale(${scale})`)})}
function zoomMap(direction){if(direction==='reset'){mapBox={x:0,y:0,w:1000,h:500}}else{const ratio=direction==='in'?.7:1/.7;const w=Math.max(100,Math.min(1200,mapBox.w*ratio)),h=w/2;mapBox={x:mapBox.x+(mapBox.w-w)/2,y:mapBox.y+(mapBox.h-h)/2,w,h}}applyMapBox()}
function countryTip(id,name){const el=$('#map-tip');if(!el)return;el.textContent=`${cn(id,name)} · ${t(data.places.some(p=>p.country===id)?'visitedCountry':'unvisitedCountry')}`;el.classList.add('visible')}
function exportData(){const blob=new Blob([JSON.stringify({app:'travelsplit',version:1,data},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='travelsplit-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function validateBackupBase(d){return d&&typeof d.profile==='string'&&d.profile.length<=40&&Array.isArray(d.trips)&&Array.isArray(d.bookings)&&Array.isArray(d.places)&&d.trips.every(tr=>typeof tr.id==='string'&&typeof local(tr.name)==='string'&&typeof local(tr.country)==='string'&&['planned','completed'].includes(tr.status)&&['mountains','forest','italy','japan'].includes(tr.image)&&/^\d{4}-\d\d-\d\d$/.test(tr.start)&&/^\d{4}-\d\d-\d\d$/.test(tr.end)&&Number.isFinite(duration(tr))&&duration(tr)>0)&&d.bookings.every(b=>typeof b.id==='string'&&typeof b.title==='string'&&d.trips.some(tr=>tr.id===b.tripId)&&['flight','stay','car','train','other'].includes(b.type)&&/^\d{4}-\d\d-\d\d$/.test(b.date)&&['RUB','EUR','USD','KZT','GBP'].includes(b.currency)&&(!b.amount||Number.isFinite(+b.amount)))&&d.places.every(p=>typeof p.id==='string'&&typeof p.city==='string'&&countries[p.country]&&Number.isFinite(p.lat)&&Math.abs(p.lat)<=90&&Number.isFinite(p.lon)&&Math.abs(p.lon)<=180)}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-country],[data-place]');if(!b)return;if(b.dataset.view){closeModal();navigate(b.dataset.view);return}if(b.dataset.trip){tripDetail(b.dataset.trip);return}if(b.dataset.booking){bookingDetail(b.dataset.booking);return}if(b.dataset.place){if(mapDrag?.moved)return;placeDetail(b.dataset.place);return}if(b.dataset.country){if(!mapDrag?.moved)countryTip(b.dataset.country,b.dataset.countryName);return}if(b.dataset.zoom){zoomMap(b.dataset.zoom);return}if(b.dataset.filter){filter=b.dataset.filter;render();return}if(b.dataset.bookingFilter){filter=b.dataset.bookingFilter;render();return}if(b.dataset.detailTab){tripDetail(detailId,b.dataset.detailTab);return}if(b.dataset.addTripBooking){createBooking(b.dataset.addTripBooking);return}if(b.dataset.toggleStatus){const tr=data.trips.find(tr=>tr.id===b.dataset.toggleStatus);tr.status=tr.status==='planned'?'completed':'planned';persist();render();tripDetail(tr.id,detailTab);return}if(b.dataset.deleteTrip){const id=b.dataset.deleteTrip;openModal(t('delete'),`<h2>${t('confirmDelete')}</h2><p class="description">${t('deleteTripWarning')}</p><div class="form-actions"><button class="ghost" data-trip="${esc(id)}">${t('cancel')}</button><button class="primary" data-confirm-delete-trip="${esc(id)}">${t('delete')}</button></div>`);return}if(b.dataset.confirmDeleteTrip){if(!canManageTrip(b.dataset.confirmDeleteTrip)){toast(ct('noManage'));return}cleanupTripCollaboration(b.dataset.confirmDeleteTrip);data.trips=data.trips.filter(tr=>tr.id!==b.dataset.confirmDeleteTrip);data.bookings=data.bookings.filter(br=>br.tripId!==b.dataset.confirmDeleteTrip);persist();closeModal();render();toast(t('deleted'));return}if(b.dataset.deleteBooking){data.bookings=data.bookings.filter(br=>br.id!==b.dataset.deleteBooking);persist();closeModal();render();toast(t('deleted'));return}if(b.dataset.deletePlace){data.places=data.places.filter(p=>p.id!==b.dataset.deletePlace);persist();closeModal();render();toast(t('deleted'));return}if(b.dataset.focusPlace){atlasMode='world';const p=data.places.find(p=>p.id===b.dataset.focusPlace);closeModal();mapBox={x:(p.lon+180)/360*1000-120,y:(90-p.lat)/180*500-60,w:240,h:120};navigate('atlas');return}const action=b.dataset.action;if(action==='create-trip')createTrip();if(action==='create-booking')createBooking();if(action==='create-place')createPlace();if(action==='cancel')closeModal();if(action==='next'||action==='prev'){const count=visibleTrips().filter(tr=>tr.status==='planned').length||visibleTrips().length;slide=(slide+(action==='next'?1:-1)+Math.max(count,1))%Math.max(count,1);render()}if(action==='export')exportData();if(action==='install'){if(deferredInstall){deferredInstall.prompt();deferredInstall=null}else toast(t('installHint'))}});
$('#theme').addEventListener('click',()=>{theme=theme==='dark'?'light':'dark';Store.setPref('theme',theme);setTheme()});$('#language').addEventListener('click',()=>{lang=lang==='ru'?'en':'ru';Store.setPref('lang',lang);closeModal();render()});$('#profile').addEventListener('click',profile);$('#close-modal').addEventListener('click',closeModal);$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
document.addEventListener('input',e=>{if(e.target.id==='trip-search'){query=e.target.value;$('#trip-results').innerHTML=tripResults()}if(e.target.name==='start'){const end=$('#trip-form [name=end]');if(end)end.min=e.target.value}});
document.addEventListener('change',async e=>{if(e.target.name==='preset'&&e.target.value!==''){const c=cityPresets[+e.target.value],f=$('#place-form');f.elements.city.value=c[0];f.elements.cityEn.value=c[1];f.elements.country.value=c[2];f.elements.lat.value=c[3];f.elements.lon.value=c[4]}if(e.target.id==='import-data'&&e.target.files[0]){try{const file=e.target.files[0];if(file.size>5e6)throw Error();const parsed=JSON.parse(await file.text());if(parsed.app!=='travelsplit'||!validateBackup(parsed.data))throw Error();data=parsed.data;persist();closeModal();render();toast(t('importSuccess'))}catch(err){toast(t('importError'))}}});
document.addEventListener('submit',e=>{const f=e.target;if(!['trip-form','booking-form','place-form','notes-form','profile-form'].includes(f.id))return;e.preventDefault();const v=Object.fromEntries(new FormData(f)),id=uid();if(f.id==='trip-form'){if(v.end<v.start){$('#form-error').textContent=t('invalidDates');return}if(!v.name.trim()||!v.country.trim())return;data.trips.push({id,name:v.name.trim(),country:v.country.trim(),start:v.start,end:v.end,status:v.status,image:v.image,notes:v.notes.trim()});persist();closeModal();navigate('trips');toast(t('tripCreated'))}if(f.id==='booking-form'){if(!v.title.trim())return;data.bookings.push({...v,id,title:v.title.trim()});persist();closeModal();navigate('bookings');toast(t('bookingSaved'))}if(f.id==='place-form'){if(!v.city.trim())return;if(data.places.some(p=>p.country===v.country&&p.city.toLowerCase()===v.city.trim().toLowerCase())){$('#form-error').textContent=t('duplicate');return}data.places.push({id,city:v.city.trim(),cityEn:v.cityEn.trim()||v.city.trim(),country:v.country,lat:+v.lat,lon:+v.lon});persist();closeModal();navigate('atlas');toast(t('placeSaved'))}if(f.id==='notes-form'){const tr=data.trips.find(tr=>tr.id===f.dataset.id);tr.notes=v.notes.trim();persist();tripDetail(tr.id,'notes');toast(t('saved'))}if(f.id==='profile-form'){if(!v.profile.trim())return;data.profile=v.profile.trim();currentMember().displayName=data.profile;persist();closeModal();render();toast(t('profileSaved'))}});
document.addEventListener('keydown',e=>{const c=e.target.closest('[data-country],.map-marker');if(c&&['Enter',' '].includes(e.key)){e.preventDefault();c.dispatchEvent(new MouseEvent('click',{bubbles:true}))}});
document.addEventListener('pointerdown',e=>{const svg=e.target.closest('svg.world');if(!svg)return;mapDrag={x:e.clientX,y:e.clientY,box:{...mapBox},moved:false,pointer:e.pointerId}});
document.addEventListener('pointermove',e=>{if(!mapDrag||e.pointerId!==mapDrag.pointer)return;const svg=$('svg.world');if(!svg)return;const dx=e.clientX-mapDrag.x,dy=e.clientY-mapDrag.y;if(Math.abs(dx)+Math.abs(dy)>5)mapDrag.moved=true;if(mapDrag.moved){const rect=svg.getBoundingClientRect(),ratio=Math.min(rect.width/mapBox.w,rect.height/mapBox.h);mapBox.x=Math.max(-250,Math.min(1100-mapBox.w,mapDrag.box.x-dx/ratio));mapBox.y=Math.max(-200,Math.min(650-mapBox.h,mapDrag.box.y-dy/ratio));applyMapBox()}});
document.addEventListener('pointerup',()=>{setTimeout(()=>{mapDrag=null},80)});document.addEventListener('pointercancel',()=>{mapDrag=null});window.addEventListener('resize',()=>{if(view==='atlas')applyMapBox()});window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(['home','trips','bookings','atlas','photos'].includes(v)){view=v;filter='all';query='';render()}});window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e});
view=['home','trips','bookings','atlas','photos'].includes(location.hash.slice(1))?location.hash.slice(1):'home';render();if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('sw.js').catch(()=>{});
